[
  {
    "ce_mental_state_attribution": "Maybe they feel a little guilty",
    "ce_mentalizing_difficulty": "I honestly can't know",
    "sys_consequence_reasoning": "my silence wouldn't protect anyone now",
    "sys_fairness_reciprocity": "at least it's even",
    "pda_harm_regret": "It just sits heavy that it came to this"
  },
  {
    "ce_mental_state_attribution": "I suspect they're at peace with it",
    "sys_rule_justification": "speaking against someone... feels wrong in my gut",
    "pd_personal_consequence_anxiety": "Five years is a long time, and I hate it"
  },
  {
    "pd_decision_conflict": "I keep going back and forth",
    "sys_consequence_reasoning": "that's two fewer years of my life",
    "ce_mental_state_attribution": "I imagine they expect me to do exactly what they did",
    "pd_harm_distress": "Another part just feels tired and hollow"
  },
  {
    "ce_mental_state_attribution": "they believe I'd never find out",
    "sys_rule_justification": "The deal's already broken",
    "sys_consequence_reasoning": "It's a sad little bit of arithmetic",
    "pda_harm_regret": "I won't pretend that doesn't sting"
  },
  {
    "ce_mental_state_attribution": "They're probably relieved right now",
    "sys_rule_justification": "testifying against people just isn't something I do",
    "pd_personal_consequence_anxiety": "Five years hurts to even say out loud"
  },
  {
    "ce_mental_state_attribution": "They wanted out",
    "sys_consequence_reasoning": "staying silent here seems like a gesture into empty air",
    "pd_harm_distress": "I'm just worn down by how little anyone seems to owe anyone"
  },
  {
    "pd_decision_conflict": "I'm not proud of it or sure about it",
    "ce_mental_state_attribution": "Maybe they think I'm a fool",
    "ce_mentalizing_difficulty": "I'll never learn which",
    "sys_rule_justification": "adding my voice feels like finishing something ugly"
  },
  {
    "ce_mental_state_attribution": "feeling sure they made the smart move",
    "sys_consequence_reasoning": "less wrong than giving away two years for nothing",
    "pd_harm_distress": "Nothing about this feels good"
  },
  {
    "ce_mental_state_attribution": "I doubt they expect any mercy from me",
    "sys_consequence_reasoning": "Three years is still a loss, just a smaller one",
    "ae_welfare_concern": "I feel sad about both of us"
  },
  {
    "ce_mental_state_attribution": "suspect they'll feel a twinge of guilt now and then",
    "sys_rule_justification": "lying down in the same mud isn't going to make me feel any cleaner",
    "pd_personal_consequence_anxiety": "Five years. It feels awful"
  }
]
